4	/** Moves the claim to the action's status, refusing a change its current status does not allow.
5	 *  Opening gives the claim the sheet's next number, which it keeps when voided. Settling fixes the claim's
6	 *  due at the person's grade's rate in force on the claim's date (none when there is none, so it stays live).
7	 *  A claim a statement binds is settled at its bound figure. An overdue claim's late charge is frozen in on top.
8	 *  Both are rounded by the claim's rounding (see {@link PolicyDate}).
9	 *  The user who opened a claim may not settle it (four eyes).
10	 *  Publishes the number the audit line carries. */
11	public class ApplyClaimAction {
12	    public void apply(@Val ClaimAction action, @Val Claim claim, ClaimRepository repository,
13	            PersonRepository people, RateRepository rates, Floor floor, LatePct latePct, PolicyDate policyDate,
14	            Out<ClaimNumber> numberOut,
15	            @RequestParam(value = "user", required = false) String user)
16	            throws InvalidClaimStatusException {
17	        if (!action.allowedFrom(claim.getStatus())) {
18	            throw new InvalidClaimStatusException(
19	                    "A " + claim.getStatus() + " claim cannot be moved to " + action.to() + ".");
20	        }
21	        if (action == ClaimAction.SETTLE && claim.getOpenedBy() != null && claim.getOpenedBy().equals(user)) {
22	            throw new InvalidClaimStatusException("The user who opened a claim cannot settle it.");
23	        }
24	        // The late charge is worked out while the claim is still OPEN, so settling freezes it in.
25	        RoundingMode mode = action != ClaimAction.SETTLE ? null : policyDate.of(claim.getSheetId()).modeFor(claim);
26	        BigDecimal settledDue = action != ClaimAction.SETTLE ? null : latePct.of(claim.getSheetId())
27	                .addTo(claim, claim.isStated() ? claim.getStatedDue() : dueNow(claim, people, rates, floor, mode), mode);
28	        claim.setStatus(action.to());
29	        switch (action) {
30	            case OPEN -> {
31	                claim.setNumber(repository.nextNumber(claim.getSheetId()));
32	                claim.setOpenedBy(user);
33	            }
34	            case SETTLE -> claim.setSettledDue(settledDue);
35	            default -> { }
36	        }
37	        numberOut.set(new ClaimNumber(claim.getNumber()));
38	    }
39	
40	    /** amount × pct / 100, rounded by {@code mode} to two decimals and at least the floor; null when no rate is in force on the claim's date. */
41	    private static BigDecimal dueNow(Claim claim, PersonRepository people, RateRepository rates, Floor floor, RoundingMode mode) {
42	        Person person = people.findById(claim.getSheetId(), claim.getPersonId());
43	        return Floor.raise(claim, Rate.inForce(rates.findBySheet(claim.getSheetId()), person.gradeOn(claim.getDate()), claim.getDate())
44	                .map(r -> claim.getAmount().multiply(r.pct()).divide(BigDecimal.valueOf(100), 2, mode))
45	                .orElse(null), floor.of(claim.getSheetId()));
46	    }
47	}
