49	/** The sheet's late percent (two decimals, 0.00 until set). An overdue claim (OPEN, its due-by — its
50	 *  date plus the terms — before the sheet's today) gains the late percent of its figure for every full
51	 *  30 days it is overdue, rounded to two decimals by the claim's rounding (see {@link PolicyDate}), on top. The charge is never bound by a
52	 *  statement; settling freezes it into the settled due. A correction (a negative amount) has no late charge. */
53	@Service
54	public class LatePct {
55	    public static final String KEY = "late-pct";
56	    public static final String DEFAULT = "0.00";
57	    private final SettingRepository settings;
58	    private final SheetClock clock;
59	    public LatePct(SettingRepository settings, SheetClock clock) {
60	        this.settings = settings;
61	        this.clock = clock;
62	    }
63	    /** The late charge as it stands on the sheet's today. */
64	    public Charge of(String sheetId) {
65	        return new Charge(new BigDecimal(settings.find(sheetId, KEY).orElse(DEFAULT)),
66	                Integer.parseInt(settings.find(sheetId, Terms.KEY).orElse(Terms.DEFAULT)), clock.today(sheetId));
67	    }
68	    /** The late percent, the terms and the day the charge is worked out on. */
69	    public record Charge(BigDecimal pct, int terms, LocalDate today) {
70	        /** The figure with the claim's late charge, rounded by {@code mode}, on top; null (n/a) stays null. */
71	        public BigDecimal addTo(Claim claim, BigDecimal figure, RoundingMode mode) {
72	            if (figure == null || claim.getStatus() != ClaimStatus.OPEN || claim.isCorrection()) return figure;
73	            long late = ChronoUnit.DAYS.between(claim.getDate().plusDays(terms), today);
74	            if (late <= 0) return figure;
75	            long periods = late / 30;
76	            return figure.add(figure.multiply(pct).multiply(BigDecimal.valueOf(periods))
77	                    .divide(BigDecimal.valueOf(100), 2, mode));
78	        }
79	    }
80	}
