97	    /** The rounding policy as it stands on the sheet now. */
98	    public Policy of(String sheetId) {
99	        LocalDate date = settings.find(sheetId, KEY).map(LocalDate::parse).orElseGet(() -> clock.today(sheetId));
100	        return new Policy(date, claims.findBySheet(sheetId));
