102	    /** The policy date and the sheet's claims, which a correction's corrected claim is found among. */
103	    public record Policy(LocalDate date, List<Claim> claims) {
104	        /** How the claim's live figures round. */
105	        public RoundingMode modeFor(Claim claim) {
106	            return roundsOn(claim).isBefore(date) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
