167	public class ValidateSetting {
168	    /** 0 or more, with up to two decimals. */
169	    private static final Pattern MONEY = Pattern.compile("\\d+(\\.\\d{1,2})?");
170	    /** A whole number of days, 0 or more. */
171	    private static final Pattern DAYS = Pattern.compile("\\d{1,4}");
172	    public void validate(@PathVariable("sheetId") String sheetId, @PathVariable("key") String key,
173	            @RequestBody SettingRequest request, Out<Setting> setting) throws InvalidSettingException {
174	        String value = request == null || request.value() == null ? "" : request.value().strip();
175	        if (!ClerkLimit.KEY.equals(key) && !Floor.KEY.equals(key) && !Terms.KEY.equals(key)
176	                && !LatePct.KEY.equals(key) && !PolicyDate.KEY.equals(key)) {
177	            throw new InvalidSettingException("No such setting: " + key);
178	        }
179	        if (PolicyDate.KEY.equals(key)) {
180	            if (!value.isEmpty()) {
181	                try {
182	                    value = LocalDate.parse(value).toString();
183	                } catch (DateTimeParseException e) {
184	                    throw new InvalidSettingException("The policy date must be blank or a date (yyyy-MM-dd).");
185	                }
186	            }
187	        } else if (Terms.KEY.equals(key)) {
188	            if (!DAYS.matcher(value).matches()) {
189	                throw new InvalidSettingException("The terms must be a whole number of days.");
190	            }
191	            value = String.valueOf(Integer.parseInt(value));
192	        } else if (Floor.KEY.equals(key)) {
193	            if (!MONEY.matcher(value).matches()) {
194	                throw new InvalidSettingException("The floor must be an amount with up to two decimals.");
195	            }
