292	/**
293	 * Takes a statement for the person: works out their due-total as the screen shows it, binds each of
294	 * their claims that counts (OPEN or SETTLED) to the figure it has now, unbinds the rest
295	 * (leaving a held person's OPEN claims, which count in no total, as they are), and moves
296	 * the person's statement count, last due-total and date (the sheet's today) on.
297	 *
298	 * A claim's figure is its settled due, else the figure a statement bound it to, else its live due at
299	 * the rate of the person's grade in force on its date (the grade in force on that date too), at least the sheet's floor (n/a without a rate). The due-total adds up the counting
300	 * claims' figures, each with its late charge on top (see {@link LatePct}; the bound figure leaves it out, so it
301	 * keeps following the sheet's today), skipping n/a; it is n/a when the grade in force on today has no rate there and no counting claim
302	 * has a figure.
303	 */
304	public class TakeStatement {
305	    public void take(@Val Person person, ClaimRepository claims, PersonRepository people, RateRepository rateRepository,
306	            SheetClock clock, Floor floor, LatePct latePct, PolicyDate policyDate, Out<Statement> statementOut) {
307	        String sheetId = person.getSheetId();
308	        LocalDate today = clock.today(sheetId);
309	        List<Rate> rates = rateRepository.findBySheet(sheetId);
310	        BigDecimal least = floor.of(sheetId);
311	        LatePct.Charge late = latePct.of(sheetId);
312	        PolicyDate.Policy policy = policyDate.of(sheetId);
313	        BigDecimal sum = BigDecimal.ZERO.setScale(2);
314	        boolean figured = false;
315	        int counted = 0;
316	        for (Claim claim : claims.findByPerson(sheetId, person.getId())) {
317	            boolean counts = claim.getStatus() == ClaimStatus.OPEN || claim.getStatus() == ClaimStatus.SETTLED;
318	            if (counts && !person.counts(claim.getStatus())) {
319	                continue;           // a held person's OPEN claim: in no total, and left as it is
320	            } else if (!counts) {
321	                claim.setStated(false);
322	                claim.setStatedDue(null);
323	            } else {
324	                RoundingMode mode = policy.modeFor(claim);
325	                BigDecimal figure = figure(claim, person, rates, least, mode);
326	                if (figure != null) figured = true;
327	                BigDecimal due = late.addTo(claim, figure, mode);
328	                if (due != null) sum = sum.add(due);
329	                claim.setStated(true);
330	                claim.setStatedDue(figure);
331	                counted++;
332	            }
333	            claims.save(claim);
334	        }
335	        BigDecimal dueTotal = Rate.inForce(rates, person.gradeOn(today), today).isEmpty() && !figured ? null : sum;
336	        person.setStatementCount(person.getStatementCount() + 1);
337	        person.setStatedTotal(dueTotal);
338	        person.setStatementDate(today);
339	        people.saveStatement(person);
340	        statementOut.set(new Statement(dueTotal, counted));
341	    }
342	    /** amount × pct / 100, rounded by {@code mode} to two decimals and at least the floor, unless already fixed; null when n/a. */
343	    private static BigDecimal figure(Claim claim, Person person, List<Rate> rates, BigDecimal least, RoundingMode mode) {
344	        if (claim.getSettledDue() != null) return claim.getSettledDue();
345	        if (claim.isStated()) return claim.getStatedDue();
346	        return Floor.raise(claim, Rate.inForce(rates, person.gradeOn(claim.getDate()), claim.getDate())
347	                .map(r -> claim.getAmount().multiply(r.pct()).divide(BigDecimal.valueOf(100), 2, mode))
348	                .orElse(null), least);
349	    }
350	}
