362	 * The sheet's figures as the screen shows them: each person's claimed and due-total, in the order
363	 * they were added, and the sheet's claimed-total and due-total.
364	 *
365	 * Only OPEN and SETTLED claims count, and a held person's OPEN claims do not. A claim's figure is its settled due, else the figure a statement
366	 * bound it to, else its live due at the person's grade's rate in force on its date, at least the sheet's floor
367	 * (n/a without a rate), plus the late charge of an overdue OPEN claim (see {@link LatePct}), each rounded by the
368	 * claim's rounding (see {@link PolicyDate}).
369	 * A person's due-total adds up their counting claims' figures, skipping n/a; it is n/a when the grade
370	 * in force on the sheet's today has no rate there and no counting claim has a figure. The sheet's due-total
371	 * adds up the people's due-totals, skipping n/a.
372	 */
373	@Service
374	public class Rollup {
375	    static final String NA = "n/a";
376	    /** One person's figures, as text with two decimals (due-total may be n/a). */
377	    public record Figures(String name, String claimed, String dueTotal) {
378	        boolean sameAs(Figures other) {
379	            return other != null && claimed.equals(other.claimed) && dueTotal.equals(other.dueTotal);
380	        }
381	    }
382	    /** The sheet's figures at one moment: people by id, in the order they were added, and the totals. */
383	    public record Snapshot(Map<Long, Figures> people, String claimedTotal, String dueTotal) {
384	        boolean sameTotals(Snapshot other) {
385	            return claimedTotal.equals(other.claimedTotal) && dueTotal.equals(other.dueTotal);
386	        }
387	    }
388	    private final PersonRepository people;
389	    private final ClaimRepository claims;
390	    private final RateRepository rates;
391	    private final SheetClock clock;
392	    private final Floor floor;
393	    private final LatePct latePct;
394	    private final PolicyDate policyDate;
395	    public Rollup(PersonRepository people, ClaimRepository claims, RateRepository rates, SheetClock clock, Floor floor,
396	            LatePct latePct, PolicyDate policyDate) {
397	        this.policyDate = policyDate;
398	        this.floor = floor;
399	        this.latePct = latePct;
400	        this.people = people;
401	        this.claims = claims;
402	        this.rates = rates;
403	        this.clock = clock;
404	    }
405	    public Snapshot take(String sheetId) {
406	        LocalDate today = clock.today(sheetId);
407	        List<Rate> sheetRates = rates.findBySheet(sheetId);
408	        List<Claim> sheetClaims = claims.findBySheet(sheetId);
409	        BigDecimal least = floor.of(sheetId);
410	        LatePct.Charge late = latePct.of(sheetId);
411	        PolicyDate.Policy policy = policyDate.of(sheetId);
412	        Map<Long, Figures> figures = new LinkedHashMap<>();
413	        BigDecimal claimedTotal = zero();
414	        BigDecimal dueTotal = zero();
415	        for (Person person : people.findBySheet(sheetId)) {
416	            BigDecimal claimed = zero();
417	            BigDecimal due = zero();
418	            boolean figured = false;
419	            for (Claim claim : sheetClaims) {
420	                if (claim.getPersonId() != person.getId()) continue;
421	                if (!person.counts(claim.getStatus())) continue;
422	                claimed = claimed.add(claim.getAmount());
423	                RoundingMode mode = policy.modeFor(claim);
424	                BigDecimal figure = late.addTo(claim, figure(claim, person, sheetRates, least, mode), mode);
425	                if (figure != null) {
426	                    due = due.add(figure);
427	                    figured = true;
428	                }
429	            }
430	            boolean na = Rate.inForce(sheetRates, person.gradeOn(today), today).isEmpty() && !figured;
431	            claimedTotal = claimedTotal.add(claimed);
432	            if (!na) dueTotal = dueTotal.add(due);
433	            figures.put(person.getId(), new Figures(person.getName(), text(claimed), na ? NA : text(due)));
434	        }
435	        return new Snapshot(figures, text(claimedTotal), text(dueTotal));
436	    }
437	    /** The due-total of the sheet's counting claims dated from {@code from} to {@code to}, both included:
438	     *  each claim's figure at its person's grade, skipping n/a. */
439	    public BigDecimal dueTotal(String sheetId, LocalDate from, LocalDate to) {
440	        List<Rate> sheetRates = rates.findBySheet(sheetId);
441	        List<Claim> sheetClaims = claims.findBySheet(sheetId);
442	        BigDecimal least = floor.of(sheetId);
443	        LatePct.Charge late = latePct.of(sheetId);
444	        PolicyDate.Policy policy = policyDate.of(sheetId);
445	        BigDecimal sum = zero();
446	        for (Person person : people.findBySheet(sheetId)) {
447	            for (Claim claim : sheetClaims) {
448	                if (claim.getPersonId() != person.getId()) continue;
449	                if (!person.counts(claim.getStatus())) continue;
450	                if (claim.getDate().isBefore(from) || claim.getDate().isAfter(to)) continue;
451	                RoundingMode mode = policy.modeFor(claim);
452	                BigDecimal figure = late.addTo(claim, figure(claim, person, sheetRates, least, mode), mode);
453	                if (figure != null) sum = sum.add(figure);
454	            }
455	        }
456	        return sum.setScale(2, RoundingMode.HALF_EVEN);
457	    }
458	    /** The ROLLUP lines for each person whose figures moved since {@code before} (a new person counts
459	     *  as moved), then a TOTALS line when the sheet's totals moved. */
460	    public List<String> changes(String sheetId, String user, Snapshot before, Snapshot after) {
461	        String prefix = " sheet=" + sheetId + " by=" + user;
462	        List<String> lines = new ArrayList<>();
463	        after.people().forEach((id, now) -> {
464	            if (!now.sameAs(before.people().get(id))) {
465	                lines.add("ROLLUP" + prefix + " person=" + now.name() + " claimed=" + now.claimed()
466	                        + " due-total=" + now.dueTotal());
467	            }
468	        });
469	        if (!after.sameTotals(before)) {
470	            lines.add("TOTALS" + prefix + " claimed-total=" + after.claimedTotal() + " due-total=" + after.dueTotal());
471	        }
472	        return lines;
473	    }
474	    private static BigDecimal figure(Claim claim, Person person, List<Rate> rates, BigDecimal least, RoundingMode mode) {
475	        if (claim.getSettledDue() != null) return claim.getSettledDue();
476	        if (claim.isStated()) return claim.getStatedDue();
477	        return Floor.raise(claim, Rate.inForce(rates, person.gradeOn(claim.getDate()), claim.getDate())
478	                .map(r -> claim.getAmount().multiply(r.pct()).divide(BigDecimal.valueOf(100), 2, mode))
479	                .orElse(null), least);
480	    }
481	    private static BigDecimal zero() {
482	        return BigDecimal.ZERO.setScale(2);
483	    }
484	    private static String text(BigDecimal value) {
485	        return Objects.requireNonNull(value).setScale(2, RoundingMode.HALF_EVEN).toPlainString();
486	    }
