546	/**
547	 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
548	 * so tests can assert side-effects by reading that file — the second test-assertion channel
549	 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
550	 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
551	 *
552	 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
553	 * SYNC) so a test reads the record immediately.
554	 */
555	@Service
556	public class Audit {
557	    private final Path file;
558	    public Audit(@Value("${app.audit.file:.run/audit.log}") String path) {
559	        this.file = Path.of(path);
560	    }
561	    /** Append one audit record. Tests assert the exact line(s) in the file. */
562	    public synchronized void record(String entry) {
563	        try {
564	            Path parent = file.toAbsolutePath().getParent();
565	            if (parent != null) {
566	                Files.createDirectories(parent);
567	            }
568	            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
569	                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
570	        } catch (IOException e) {
571	            throw new UncheckedIOException(e);
572	        }
573	    }
574	    /** Remove the audit file. */
575	    public synchronized void clear() {
576	        try {
577	            Files.deleteIfExists(file);
578	        } catch (IOException e) {
579	            throw new UncheckedIOException(e);
580	        }
581	    }
582	}
