claims/Claims.tsx:  settledDue: string | null;
claims/Claims.tsx:  /** The user who opened the claim; null until it is opened. That user may not settle it. */
claims/Claims.tsx:  openedBy: string | null;
claims/Claims.tsx:  /** Whether the person's last statement bound the claim to `statedDue`. */
claims/Claims.tsx:  stated: boolean;
claims/Claims.tsx:  /** The figure the last statement bound the claim to; null when unbound, or bound without a rate (n/a). */
claims/Claims.tsx:  statedDue: string | null;
claims/Claims.tsx:  /** The number of the SETTLED claim this correction (a negative amount) corrects; null for any other claim. */
claims/Claims.tsx:  corrects: number | null };
