import { type Period, inPeriod, periodsKey, periodsPath, usePeriods } from './usePeriods';

// The sheet's periods, added here, each with its due-total: the figures of the claims that count
// (not a held person's OPEN claims)
// whose date falls in it, each at the rate in force on its date of its person's grade in force on that date, skipping n/a.
// A closed period shows the due-total it was closed at instead, whatever rates do later, until a steward reopens it.
export function Periods({ sheet }: { sheet: string }) {
  const periods = usePeriods(sheet);
  const dueTotalOf = usePeriodDueTotal(sheet);

  return (
    <section>
      <h2>Periods</h2>
      <PeriodForm sheet={sheet} />
      <table>
        <thead>
          <tr>
            <th>Name</th>
            <th>From</th>
            <th>To</th>
            <th>Due total</th>
            <th>Closed</th>
            <th />
          </tr>
        </thead>
        <tbody>
          {periods.map((p) => (
            <PeriodRow key={p.name} sheet={sheet} period={p}
              dueTotal={dueTotalOf(p)} />
          ))}
        </tbody>
      </table>
    </section>
  );
}

/** A period's due-total as its row shows it: the one it was closed at while it is closed, else
 *  worked out from the claims that count. */
export function usePeriodDueTotal(sheet: string): (period: Period) => string {
  const people = usePeople(sheet);
  const claims = useClaims(sheet);
  const rates = useRates(sheet);
  const floor = useFloor(sheet);
  const late = useLate(sheet);
  const personOf = new Map(people.map((p) => [p.id, p]));
  const held = new Set(people.filter((p) => p.held).map((p) => p.id));
  return (period: Period) =>
    period.closed && period.closedTotal != null ? period.closedTotal : total(claims
      .filter((c) => counts(c, held.has(c.personId)) && inPeriod(period, c.date) && personOf.has(c.personId))
      .map((c) => claimDue(c, rateOn(rates, gradeOn(personOf.get(c.personId)!, c.date), c.date), floor, late)));
}

// The sheet's rates for each grade: a percent with two decimals, set here, each in force from its
// from-date (null: from the beginning of time). A claim uses its grade's rate in force on its date;
// with none it shows n/a, and so does anything due that depends on it. Money and percents come from
// the server as strings with two decimals and are worked in whole cents and hundredths of a percent,
// never floats.
export type Rate = { grade: string; pct: string; from: string | null };

const GRADES = ['A', 'B', 'C'];
export const NA = 'n/a';

export const ratesKey = (sheet: string) => ['sheet', sheet, 'rates'];
const ratesPath = (sheet: string) => `/api/sheets/${encodeURIComponent(sheet)}/rates`;

export function useRates(sheet: string): Rate[] {
  return (
    useQuery({
      queryKey: ratesKey(sheet),
      queryFn: () => getJson<Rate[]>(ratesPath(sheet)),
      enabled: !!sheet,
    }).data ?? []
  );
}

/** The grade's percent in force on the date (yyyy-MM-dd): the rate with the latest from-date on or
 *  before it. Undefined when no rate is in force then, or the date is not known yet. */
export function rateOn(rates: Rate[], grade: string, date: string | undefined): string | undefined {
  if (date === undefined) return undefined;
  let best: Rate | undefined;
  for (const r of rates) {
    if (r.grade !== grade || (r.from !== null && r.from > date)) continue;
    if (best === undefined || (best.from ?? '') < (r.from ?? '')) best = r;
  }
  return best?.pct;
}

/** A two-decimal string (a correction's is negative) as a whole number of hundredths. */
export const toHundredths = (value: string): bigint => {
  const negative = value.startsWith('-');
  const [whole, frac = ''] = (negative ? value.slice(1) : value).split('.');
  const h = BigInt(whole) * 100n + BigInt(frac.padEnd(2, '0') || '0');
  return negative ? -h : h;
};

/** Hundredths as a two-decimal string, with a minus sign when negative. */
export const fromHundredths = (h: bigint): string => {
  const abs = h < 0n ? -h : h;
  return `${h < 0n ? '-' : ''}${abs / 100n}.${String(abs % 100n).padStart(2, '0')}`;
};

/** amount × pct / 100, rounded half to even (or half up, `halfUp`) to two decimals; n/a without a rate.
 *  A correction's negative amount rounds like any other, by its size, keeping its sign. */
export function due(amount: string, pct: string | undefined, halfUp = false): string {
  if (pct === undefined) return NA;
  // cents × hundredths-of-a-percent gives cents × 10000.
  const signed = toHundredths(amount) * toHundredths(pct);
  const scaled = signed < 0n ? -signed : signed;
  const rounded = roundScaled(scaled, halfUp);
  return fromHundredths(signed < 0n ? -rounded : rounded);
}

/** A non-negative cents × 10000 to cents, rounded half to even, or half up when `halfUp`. */
export function roundScaled(scaled: bigint, halfUp: boolean): bigint {
  const cents = scaled / 10000n;
  const rest = scaled % 10000n;
  return rest > 5000n || (rest === 5000n && (halfUp || cents % 2n === 1n)) ? cents + 1n : cents;
}

/** Two-decimal values added up, skipping n/a. */
export function total(values: string[]): string {
  return fromHundredths(values.filter((v) => v !== NA).reduce((sum, v) => sum + toHundredths(v), 0n));
}

